/* APP_CACHE and APP_FILES are generated by Vite for each build. */
const APP_CACHE_PREFIX = 'myrsuh-app-'
const appPaths = new Set(APP_FILES)

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(APP_CACHE).then(cache =>
      cache.addAll(APP_FILES.map(path => new Request(path, { cache: 'reload' })))
    )
  )
})

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys()
    await Promise.all(keys
      .filter(key => key.startsWith(APP_CACHE_PREFIX) && key !== APP_CACHE)
      .map(key => caches.delete(key)))
    await self.clients.claim()
  })())
})

self.addEventListener('fetch', event => {
  const { request } = event
  const url = new URL(request.url)
  if (request.method !== 'GET' || url.origin !== self.location.origin) return

  const isHome = request.mode === 'navigate' && url.pathname === '/'
  const path = isHome ? '/index.html' : url.pathname
  if (!appPaths.has(path)) return

  event.respondWith((async () => {
    const cache = await caches.open(APP_CACHE)
    return (await cache.match(path)) ?? fetch(request)
  })())
})
